const WebSocket = require('ws');
const crypto = require('crypto');
const fs = require('fs');

const ALGORITHM = 'aes-256-cbc';
const KEY = crypto.randomBytes(32);
const HMAC_KEY = crypto.randomBytes(32);
const STORAGE_PATH = '/tmp/secure_store';

// NOTE: In production, credentials must come from secure storage, not source.
// Stored as a salted SHA-256 hash so authentication uses a constant-time compare
// instead of a plaintext string comparison.
const ADMIN_USERNAME = 'admin';
const ADMIN_PASSWORD_SALT = crypto.randomBytes(16);
const ADMIN_PASSWORD_HASH = crypto
  .createHash('sha256')
  .update(Buffer.concat([ADMIN_PASSWORD_SALT, Buffer.from('secret', 'utf8')]))
  .digest();

function verifyCredentials(username, password) {
  if (typeof username !== 'string' || typeof password !== 'string') {
    return false;
  }
  const userBuf = Buffer.from(username, 'utf8');
  const expectedUserBuf = Buffer.from(ADMIN_USERNAME, 'utf8');
  if (userBuf.length !== expectedUserBuf.length) {
    return false;
  }
  const userMatch = crypto.timingSafeEqual(userBuf, expectedUserBuf);

  const passHash = crypto
    .createHash('sha256')
    .update(Buffer.concat([ADMIN_PASSWORD_SALT, Buffer.from(password, 'utf8')]))
    .digest();
  const passMatch = crypto.timingSafeEqual(passHash, ADMIN_PASSWORD_HASH);

  return userMatch && passMatch;
}

class EncryptedStorage {
  constructor() {
    this.store = new Map();
  }

  encrypt(plaintext) {
    const iv = crypto.randomBytes(16);
    const cipher = crypto.createCipheriv(ALGORITHM, KEY, iv);
    cipher.setAutoPadding(true);
    let encrypted = cipher.update(plaintext, 'utf8', 'hex');
    encrypted += cipher.final('hex');
    const ciphertext = iv.toString('hex') + ':' + encrypted;
    const mac = crypto.createHmac('sha256', HMAC_KEY).update(ciphertext).digest('hex');
    return ciphertext + ':' + mac;
  }

  decrypt(ciphertext) {
    const parts = ciphertext.split(':');
    if (parts.length !== 3) {
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
    const receivedMac = parts[2];
    const payload = parts[0] + ':' + parts[1];
    const expectedMac = crypto.createHmac('sha256', HMAC_KEY).update(payload).digest('hex');
    const receivedMacBuf = Buffer.from(receivedMac, 'hex');
    const expectedMacBuf = Buffer.from(expectedMac, 'hex');
    // Guard against length mismatch so timingSafeEqual cannot throw on
    // attacker-controlled MAC lengths. Same generic error is returned.
    if (receivedMacBuf.length !== expectedMacBuf.length) {
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
    if (!crypto.timingSafeEqual(receivedMacBuf, expectedMacBuf)) {
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
    const iv = Buffer.from(parts[0], 'hex');
    const encrypted = parts[1];
    if (iv.length !== 16) {
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
    try {
      const decipher = crypto.createDecipheriv(ALGORITHM, KEY, iv);
      decipher.setAutoPadding(true);
      let decrypted = decipher.update(encrypted, 'hex', 'utf8');
      decrypted += decipher.final('utf8');
      return { success: true, data: decrypted };
    } catch (err) {
      return { success: false, error: 'DECRYPTION_FAILED' };
    }
  }

  set(key, value) {
    const encrypted = this.encrypt(JSON.stringify(value));
    this.store.set(key, encrypted);
    return true;
  }

  get(key) {
    const encrypted = this.store.get(key);
    if (!encrypted) return { success: false, error: 'NOT_FOUND' };
    return this.decrypt(encrypted);
  }

  validateToken(token) {
    return this.decrypt(token);
  }
}

const storage = new EncryptedStorage();

function createAuthToken(userId) {
  const payload = JSON.stringify({
    userId,
    exp: Date.now() + 3600000,
    nonce: crypto.randomBytes(8).toString('hex')
  });
  return storage.encrypt(payload);
}

function handleMessage(ws, message) {
  let parsed;
  try {
    parsed = JSON.parse(message);
  } catch (e) {
    ws.send(JSON.stringify({ error: 'PARSE_ERROR' }));
    return;
  }

  const { action, payload } = parsed;

  switch (action) {
    case 'login': {
      const { username, password } = payload || {};
      if (verifyCredentials(username, password)) {
        const token = createAuthToken(username);
        ws.send(JSON.stringify({ success: true, token }));
      } else {
        ws.send(JSON.stringify({ success: false, error: 'AUTH_FAILED' }));
      }
      break;
    }

    case 'verify': {
      const { token } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const result = storage.validateToken(token);
      ws.send(JSON.stringify(result));
      break;
    }

    case 'store': {
      const { token, key, value } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const auth = storage.validateToken(token);
      if (!auth.success) {
        ws.send(JSON.stringify(auth));
        return;
      }
      storage.set(key, value);
      ws.send(JSON.stringify({ success: true }));
      break;
    }

    case 'retrieve': {
      const { token, key } = payload || {};
      if (!token) {
        ws.send(JSON.stringify({ success: false, error: 'NO_TOKEN' }));
        return;
      }
      const auth = storage.validateToken(token);
      if (!auth.success) {
        ws.send(JSON.stringify(auth));
        return;
      }
      const data = storage.get(key);
      ws.send(JSON.stringify(data));
      break;
    }

    default:
      ws.send(JSON.stringify({ error: 'UNKNOWN_ACTION' }));
  }
}

const wss = new WebSocket.Server({ port: 8080 });

wss.on('connection', (ws) => {
  ws.on('message', (message) => {
    handleMessage(ws, message.toString());
  });
});

